P=r"""<!doctype html><html lang=en><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1">
<title>Arb Screener - live crypto cross-exchange price gaps</title>
<meta name=description content="Live screener of same-coin price gaps across major crypto exchanges - KuCoin, OKX, Gate.io, MEXC, Crypto.com. USD-stable pairs, liquid, price-sanity filtered. Gross gaps before fees and tax - a monitor, not a profit promise.">
<style>
:root{--bg:#0a0e14;--p:#121820;--p2:#0f141b;--ln:#1e2730;--ink:#e6edf3;--dim:#8b9aa8;--acc:#36d399;--warn:#f5a524;--red:#f87171;--m:ui-monospace,Menlo,Consolas,monospace}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 -apple-system,Segoe UI,Roboto,sans-serif}
.wrap{max-width:1180px;margin:0 auto;padding:18px 16px 60px}
header{display:flex;align-items:center;gap:12px}
.logo{width:34px;height:34px;border-radius:8px;background:linear-gradient(135deg,#36d399,#2bb3d4);color:#06110c;font-weight:800;font-size:20px;display:flex;align-items:center;justify-content:center}
h1{font-size:18px;margin:0}.sub{color:var(--dim);font-size:12px;margin-top:2px}
.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--acc);margin-right:6px;animation:pl 2s infinite}@keyframes pl{0%,100%{opacity:1}50%{opacity:.3}}
.ban{margin:14px 0;padding:10px 12px;border:1px solid var(--ln);border-left:3px solid var(--warn);border-radius:8px;background:var(--p2);color:var(--dim);font-size:12.5px}.ban b{color:var(--ink)}
.st{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:14px 0}
.c{background:var(--p);border:1px solid var(--ln);border-radius:10px;padding:12px 14px}.c .k{color:var(--dim);font-size:11px;text-transform:uppercase;letter-spacing:.6px}.c .v{font-family:var(--m);font-size:22px;margin-top:4px;font-weight:600}
.bar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:8px 0 12px}
.bar input{background:var(--p2);border:1px solid var(--ln);color:var(--ink);border-radius:8px;padding:8px 10px;font-size:13px}.bar input[type=text]{min-width:190px}
.bar label{color:var(--dim);font-size:12px;display:flex;align-items:center;gap:6px}.ct{color:var(--dim);font-size:12px;margin-left:auto;font-family:var(--m)}
table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:8px 10px;text-align:left;border-bottom:1px solid var(--ln);white-space:nowrap}
"""
